-- Execute no SQL Editor. Preserva cadastros e ordens existentes em reexecuções.
-- Requer admin-setup.sql e categories-setup.sql já executados.
begin;
alter table public.portal_categories add column if not exists posicao integer;
with ordered as (select nome, (row_number() over(order by case nome when 'Emergência' then 0 when 'Sistemas e Consultas' then 1 when 'Sistemas Policiais' then 2 when 'Administrativo' then 3 else 4 end, nome)-1)::integer as n from public.portal_categories)
update public.portal_categories c set posicao = o.n from ordered o where c.nome = o.nome and c.posicao is null;
alter table public.portal_categories alter column posicao set default 0, alter column posicao set not null;
alter table public.atalhos_links add column if not exists posicao integer;
alter table public.atalhos_links add column if not exists grupo text;
alter table public.atalhos_links add column if not exists telefone_pendente boolean not null default false;
alter table public.atalhos_links add column if not exists origem_key text;
create unique index if not exists atalhos_links_origem_key_unique on public.atalhos_links(origem_key);
with ordered as (select id, (row_number() over(partition by categoria order by case when url = 'tel:190' then 0 else 1 end, titulo, id)-1)::integer as n from public.atalhos_links)
update public.atalhos_links a set posicao = o.n from ordered o where a.id = o.id and a.posicao is null;
alter table public.atalhos_links alter column posicao set not null;
-- Somente nomes e posições das categorias são expostos aos visitantes.
grant select(nome, posicao) on public.portal_categories to anon;
drop policy if exists portal_categories_public_order on public.portal_categories;
create policy portal_categories_public_order on public.portal_categories for select to anon using (nome <> 'Propaganda');

-- Acrescenta novos cadastros ao fim. Ao mudar de categoria, move para o fim dela.
create or replace function public.portal_append_position() returns trigger
language plpgsql set search_path = '' as $$ begin
  if TG_TABLE_NAME = 'portal_categories' then
    if TG_OP = 'INSERT' then select coalesce(max(posicao), -1) + 1 into NEW.posicao from public.portal_categories; end if;
  else
    if TG_OP = 'INSERT' or (NEW.categoria is distinct from OLD.categoria and exists(select 1 from public.portal_categories where nome = OLD.categoria)) then
      select coalesce(max(posicao), -1) + 1 into NEW.posicao from public.atalhos_links where categoria = NEW.categoria;
    end if;
  end if;
  return NEW;
end $$;
revoke all on function public.portal_append_position() from public, anon, authenticated;
drop trigger if exists portal_category_append_position on public.portal_categories;
create trigger portal_category_append_position before insert on public.portal_categories for each row execute function public.portal_append_position();
drop trigger if exists portal_link_append_position on public.atalhos_links;
create trigger portal_link_append_position before insert or update of categoria on public.atalhos_links for each row execute function public.portal_append_position();

-- Grava toda a ordem de uma vez. Não aceita listas parciais, repetidas ou de outra categoria.
create or replace function public.portal_reorder(p_kind text, p_category text, p_ids jsonb)
returns void language plpgsql security definer set search_path = '' as $$
declare expected integer; supplied integer; distinct_count integer; matched integer;
begin
  if not public.is_portal_admin() then raise exception 'Acesso exclusivo dos administradores.' using errcode = '42501'; end if;
  if p_ids is null or jsonb_typeof(p_ids) <> 'array' then raise exception 'Lista de posições inválida.'; end if;
  supplied := jsonb_array_length(p_ids);
  if supplied > 5000 then raise exception 'Lista muito grande.'; end if;
  select count(distinct value) into distinct_count from jsonb_array_elements_text(p_ids);
  if distinct_count <> supplied then raise exception 'A lista contém posições repetidas.'; end if;
  if p_kind = 'categories' then
    lock table public.portal_categories in share row exclusive mode;
    select count(*) into expected from public.portal_categories where nome <> 'Propaganda';
    select count(*) into matched from public.portal_categories c join jsonb_array_elements_text(p_ids) j on c.nome = j.value where c.nome <> 'Propaganda';
    if expected <> supplied or matched <> supplied then raise exception 'As categorias mudaram. Atualize a lista e tente novamente.'; end if;
    update public.portal_categories c set posicao = (j.ordinality - 1)::integer from jsonb_array_elements_text(p_ids) with ordinality j(value, ordinality) where c.nome = j.value;
  elsif p_kind = 'links' and p_category is not null then
    lock table public.atalhos_links in share row exclusive mode;
    select count(*) into expected from public.atalhos_links where categoria = p_category;
    select count(*) into matched from public.atalhos_links a join jsonb_array_elements_text(p_ids) j on a.id::text = j.value where a.categoria = p_category;
    if expected <> supplied or matched <> supplied then raise exception 'Os links mudaram. Atualize a lista e tente novamente.'; end if;
    update public.atalhos_links a set posicao = (j.ordinality - 1)::integer from jsonb_array_elements_text(p_ids) with ordinality j(value, ordinality) where a.id::text = j.value and a.categoria = p_category;
  else raise exception 'Tipo de ordenação inválido.';
  end if;
end $$;
revoke all on function public.portal_reorder(text, text, jsonb) from public, anon, authenticated;
grant execute on function public.portal_reorder(text, text, jsonb) to authenticated;

